CREATE OR REPLACE FUNCTION public.accept_group_invite(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id UUID;
  v_group_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify this invitation belongs to the current user and is pending
  SELECT group_id INTO v_group_id
  FROM study_group_members
  WHERE id = p_membership_id
    AND user_id = v_user_id
    AND status = 'invited';

  IF v_group_id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found or already processed';
  END IF;

  -- Accept: update status to active, reset joined_at to now
  UPDATE study_group_members
  SET status = 'active', joined_at = NOW()
  WHERE id = p_membership_id;

  -- Automatic notification cleanup: mark the corresponding notification as read
  UPDATE notifications
  SET is_read = true
  WHERE user_id = v_user_id
    AND type = 'group_invite'
    AND metadata->>'membership_id' = p_membership_id::TEXT
    AND is_read = false;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_study_group(p_name text, p_description text DEFAULT NULL::text, p_group_type text DEFAULT 'custom'::text, p_linked_course text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_group_id UUID;
  v_user_id  UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_group_type NOT IN ('system_course', 'custom') THEN
    RAISE EXCEPTION 'Invalid group_type: %. Must be system_course or custom.', p_group_type;
  END IF;

  INSERT INTO study_groups (name, description, created_by, group_type, linked_course)
  VALUES (p_name, p_description, v_user_id, p_group_type, p_linked_course)
  RETURNING id INTO v_group_id;

  INSERT INTO study_group_members (group_id, user_id, role, status)
  VALUES (v_group_id, v_user_id, 'admin', 'active');

  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.invite_to_group(p_group_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller_id UUID;
  v_is_admin BOOLEAN;
  v_group_name TEXT;
  v_inviter_name TEXT;
  v_membership_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check caller is an ACTIVE admin of this group
  SELECT EXISTS(
    SELECT 1 FROM study_group_members
    WHERE group_id = p_group_id
      AND user_id = v_caller_id
      AND role = 'admin'
      AND status = 'active'
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'Only group admins can invite members';
  END IF;

  -- Get group name and inviter name for the notification
  SELECT name INTO v_group_name FROM study_groups WHERE id = p_group_id;
  SELECT full_name INTO v_inviter_name FROM profiles WHERE id = v_caller_id;

  -- Insert as invited (UNIQUE constraint prevents duplicates)
  INSERT INTO study_group_members (group_id, user_id, role, status, invited_by)
  VALUES (p_group_id, p_user_id, 'member', 'invited', v_caller_id)
  RETURNING id INTO v_membership_id;

  -- Create notification for the invited user
  INSERT INTO notifications (user_id, type, title, message, metadata)
  VALUES (
    p_user_id,
    'group_invite',
    v_inviter_name || ' invited you to "' || v_group_name || '"',
    'Accept to start viewing shared notes and flashcards.',
    jsonb_build_object(
      'group_id', p_group_id,
      'group_name', v_group_name,
      'inviter_id', v_caller_id,
      'inviter_name', v_inviter_name,
      'membership_id', v_membership_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rename_batch_group(p_group_id uuid, p_new_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor  uuid := auth.uid();
  v_denial text;
  v_new    text;
  v_old    text;
  v_course text;
  v_inst   text;
BEGIN
  v_denial := public.admin_batch_action_denial(v_actor, p_group_id);
  IF v_denial IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: %', v_denial USING ERRCODE = '42501';
  END IF;

  v_new := btrim(regexp_replace(COALESCE(p_new_name, ''), '\s+', ' ', 'g'));
  IF v_new = '' THEN
    RAISE EXCEPTION 'Name cannot be blank';
  END IF;
  IF char_length(v_new) > 100 THEN
    RAISE EXCEPTION 'Name is too long (max 100 characters)';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('rename_batch_group'));

  SELECT name, batch_course, batch_institution INTO v_old, v_course, v_inst
    FROM public.study_groups WHERE id = p_group_id AND is_batch_group = true AND archived_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Access denied: batch_not_found' USING ERRCODE = '42501';
  END IF;

  IF v_old = v_new THEN
    RETURN jsonb_build_object('changed', false, 'name', v_old);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.study_groups g
     WHERE g.is_batch_group = true AND g.id <> p_group_id
       AND lower(btrim(regexp_replace(g.name, '\s+', ' ', 'g'))) = lower(v_new)
       AND g.batch_course      IS NOT DISTINCT FROM v_course
       AND g.batch_institution IS NOT DISTINCT FROM v_inst
  ) THEN
    RAISE EXCEPTION 'Another batch with this course and institution already uses that name';
  END IF;

  UPDATE public.study_groups SET name = v_new, updated_at = NOW() WHERE id = p_group_id;

  INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
  VALUES ('rename_batch_group', v_actor, NULL,
          jsonb_build_object('group_id', p_group_id, 'old_name', v_old, 'new_name', v_new, 'via', 'rename_batch_group'));

  RETURN jsonb_build_object('changed', true, 'old_name', v_old, 'name', v_new);
END;
$function$
